// Package volt is the runtime for code generated by the volt CLI: the
// handler shim with its error spine, the reverse-URL building blocks,
// the route-table types, and a minimal middleware set. It is stdlib-only
// . Middleware is func(http.Handler) http.Handler (R8); controller
// methods are func(http.ResponseWriter, *volt.Request, params...) error
// (R3).
package volt

import (
	"database/sql"
	"errors"
	"log/slog"
	"net/http"

	"github.com/Piechutowski/volt/nao/rt"
)

// Request wraps *http.Request with route identity.
type Request struct {
	*http.Request
	route string
	w     *statusWriter
}

// Route returns the matched route's ServeMux pattern (ROUTE-19).
func (r *Request) Route() string { return r.route }

// Committed reports whether the response header has been written. An
// error returned after commit reaches the error handler in log-only
// mode (§names-and-qualified-names of the router spec).
func (r *Request) Committed() bool { return r.w != nil && r.w.wrote }

// HandlerFunc is the controller-side shape after parameter binding.
type HandlerFunc func(http.ResponseWriter, *Request) error

// ErrorHandler consumes a handler error. When Request.Committed() is
// true it must not write status or body.
type ErrorHandler func(http.ResponseWriter, *Request, error)

// Handler adapts a HandlerFunc plus an ErrorHandler into a std
// http.Handler.
func Handler(route string, h HandlerFunc, eh ErrorHandler) http.Handler {
	if eh == nil {
		eh = DefaultErrorHandler
	}
	return http.HandlerFunc(func(w http.ResponseWriter, hr *http.Request) {
		sw := &statusWriter{ResponseWriter: w}
		req := &Request{Request: hr, route: route, w: sw}
		if err := h(sw, req); err != nil {
			eh(sw, req, err)
		}
	})
}

// DefaultErrorHandler writes the Problem ProblemOf finds for err, and for
// any other error a generic 500, logging the underlying error (spec
// §formats). On a committed response it only logs.
func DefaultErrorHandler(w http.ResponseWriter, r *Request, err error) {
	if r.Committed() {
		slog.Error("volt: handler error after response commit", "route", r.Route(), "err", err)
		return
	}
	if p, ok := ProblemOf(err); ok {
		writeProblem(w, r, p)
		return
	}
	slog.Error("volt: handler error", "route", r.Route(), "err", err)
	writeProblem(w, r, Problem{Status: http.StatusInternalServerError, Message: "internal server error"})
}

// ProblemOf is the Problem the error spine writes for err (spec §formats):
// an HTTPError's own status and message; a refused write, a *rt.Invalid,
// as 409 when a unique field error is among its fields and 422 otherwise
// (spec §changesets); a query's row miss (sql.ErrNoRows, which
// rt.ErrNotFound is) as 404; each with the details of an error that
// itemizes them. ok is false for any other error.
func ProblemOf(err error) (p Problem, ok bool) {
	var he HTTPError
	var inv *rt.Invalid
	switch {
	case errors.As(err, &he):
		p = Problem{Status: he.StatusCode(), Message: he.Error()}
	case errors.As(err, &inv):
		p = Problem{Status: http.StatusUnprocessableEntity, Message: inv.Error()}
		for _, f := range inv.Fields {
			if f.Check == "unique" {
				p.Status = http.StatusConflict
			}
		}
	case errors.Is(err, sql.ErrNoRows):
		return Problem{Status: http.StatusNotFound, Message: "not found"}, true
	default:
		return Problem{}, false
	}
	var d Detailer
	if errors.As(err, &d) {
		p.Details = d.Details()
	}
	return p, true
}

func writeProblem(w http.ResponseWriter, r *Request, p Problem) {
	f, _ := Negotiate(r)
	w.Header().Set("Content-Type", f.MIME())
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.WriteHeader(p.Status)
	_ = Encode(w, f, p)
}

// Chain composes middleware around h: the first element is outermost,
// matching pipeline declaration order.
func Chain(h http.Handler, mw ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mw) - 1; i >= 0; i-- {
		h = mw[i](h)
	}
	return h
}

type statusWriter struct {
	http.ResponseWriter
	status int
	wrote  bool
}

func (w *statusWriter) WriteHeader(code int) {
	if !w.wrote {
		w.wrote = true
		w.status = code
	}
	w.ResponseWriter.WriteHeader(code)
}

func (w *statusWriter) Write(b []byte) (int, error) {
	if !w.wrote {
		w.wrote = true
		w.status = http.StatusOK
	}
	return w.ResponseWriter.Write(b)
}

// Flush forwards http.Flusher. Flushing commits the response (the header
// goes out as 200 if not yet written).
func (w *statusWriter) Flush() {
	if f, ok := w.ResponseWriter.(http.Flusher); ok {
		if !w.wrote {
			w.wrote = true
			w.status = http.StatusOK
		}
		f.Flush()
	}
}

// Unwrap exposes the underlying writer to http.ResponseController.
func (w *statusWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

// Route is one row of the generated route table (volt_routes.go).
type Route struct {
	Method     string // "" for the any-verb
	Pattern    string // ServeMux pattern
	Spelled    string // DSL spelling
	Controller string
	Action     string
	Query      string // "pkg.Method" for a query route (§query-routes); Controller and Action are then empty
	Helper     string // reverse-URL function name, "" when none
	Params     []RouteParam
}

// RouteParam describes one captured parameter of a table row.
type RouteParam struct {
	Name string
	Type string // int, string
	Wild bool
}
